@js:
let d={};
try{d=JSON.parse(result)}catch(e){d={kind:'error',title:'页面解析失败',summary:String(e)}}
function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
const RAW='https://raw.githubusercontent.com/huoguotiankong/source-core-8d7/main/';
const CDN='https://cdn.jsdelivr.net/gh/huoguotiankong/source-core-8d7@main/';
let title=d.title||'🌈 阅读书源仓库',summary=d.summary||'',kind=d.kind||'info',buttons='',badges='',sections='';
(Array.isArray(d.badges)?d.badges:[]).forEach(function(x){badges+='<span>'+esc(x)+'</span>'});
(Array.isArray(d.sections)?d.sections:[]).forEach(function(x){sections+='<div class="card"><b>'+esc(x.title||'说明')+'</b><p>'+esc(x.text||'').replace(/\n/g,'<br>')+'</p></div>'});
function btn(text,url,alt){return '<a class="btn '+(alt?'alt':'')+'" href="'+esc(url)+'">'+esc(text)+'</a>'}
if(kind==='source'&&d.sourceUrl){
  buttons=btn('导入 / 更新此书源','legado://import/importonline?src='+d.sourceUrl,false);
  if(d.backupUrl)buttons+=btn('备用线路导入','legado://import/importonline?src='+d.backupUrl,true);
}
if(kind==='bundle'&&d.bundlePath){
  let u=RAW+d.bundlePath,b=CDN+d.bundlePath;
  buttons=btn('主线路批量导入','legado://import/importonline?src='+u,false)+btn('备用线路批量导入','legado://import/importonline?src='+b,true);
}
if(kind==='rss'&&d.rssUrl){
  buttons=btn('更新仓库订阅源','legado://import/rssSource?src='+d.rssUrl,false);
}
result='<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><style>:root{color-scheme:light dark;--bg:#f5f6fa;--card:#fff;--text:#202532;--muted:#747d90;--line:#e5e8f0;--p1:#596cff;--p2:#965cff}@media(prefers-color-scheme:dark){:root{--bg:#10131a;--card:#191e27;--text:#edf2f8;--muted:#9ba5b7;--line:#2b3340}}*{box-sizing:border-box}body{margin:0;padding:16px;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}.hero{padding:20px;border-radius:20px;color:#fff;background:linear-gradient(135deg,var(--p1),var(--p2));box-shadow:0 8px 24px rgba(89,108,255,.18)}h1{margin:0 0 8px;font-size:22px}.hero p{margin:0;line-height:1.65;font-size:14px;opacity:.96}.badges{margin-top:12px}.badges span{display:inline-block;margin:3px 6px 0 0;padding:5px 9px;border-radius:999px;background:rgba(255,255,255,.18);font-size:12px}.card{margin-top:12px;padding:15px 16px;border:1px solid var(--line);border-radius:16px;background:var(--card)}.card b{font-size:16px}.card p{margin:8px 0 0;color:var(--muted);line-height:1.7;font-size:14px}.btn{display:block;margin-top:12px;padding:14px;text-align:center;text-decoration:none;color:#fff;font-weight:700;border-radius:14px;background:linear-gradient(135deg,var(--p1),var(--p2))}.btn.alt{background:var(--card);color:var(--p1);border:1px solid var(--p1)}.foot{text-align:center;color:var(--muted);font-size:12px;padding:18px 4px 6px}</style></head><body><div class="hero"><h1>'+esc(title)+'</h1><p>'+esc(summary)+'</p><div class="badges">'+badges+'</div></div>'+sections+buttons+'<div class="foot">🌈 阅读书源仓库 · UI Beta 14</div></body></html>';
result;
